import jakarta.data.repository.*;
import java.util.List;

@Repository
public interface Students extends BasicRepository<Student, Long> {
    @Find
    List<Student> named(@By("name") String value);
}

import org.springframework.stereotype.Service;

@Service
class StudentService {
    private final StudentRepository repository;

    StudentService(StudentRepository repository) {
        this.repository = repository;
    }
}

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;

@SpringBootApplication
public class StudentApplication {
    public static void main(String[] args) {
        SpringApplication.run(StudentApplication.class, args);
    }
}

import java.util.List;
import org.springframework.data.jpa.repository.JpaRepository;

interface StudentRepository extends JpaRepository<Student, Long> {
    List<Student> findByNameAndAgeGreaterThan(String name, int age);
}
